def parse_args(a):
    "Decode native arguments to a dict. Return None when they cannot be read."
    if isinstance(a, dict): return a
    try: parsed = json.loads(a)
    except (json.JSONDecodeError, TypeError): return None
    return parsed if isinstance(parsed, dict) else None

def norm_resp(r):
    "Convert an OpenAI-style chat completion to a urai `Resp`."
    ch = r['choices'][0]
    m = ch.get('message') or {}
    text, th = split_think(m.get('content') or '')
    text, tag_tcs, failed = parse_tool_tags_ex(text)
    tcs = []
    for tc in m.get('tool_calls') or []:
        f = tc.get('function') or {}
        args = parse_args(f.get('arguments'))
        call = {'id': tc.get('id'), 'type': 'function',
                'function': {'name': f.get('name', ''), 'arguments': args if args is not None else {}}}
        if args is None: call['unread'] = True; failed = True
        tcs.append(call)
    tcs += tag_tcs
    res = {'role': 'assistant', 'content': text}
    if th: res['channels'] = {'thought': th}
    if tcs: res['tool_calls'] = tcs
    if failed: res['tool_parse_failed'] = True   # `_fix_step` asks for the call again
    if ch.get('finish_reason') == 'length': res['truncated'] = True
    if 'usage' in r: res['usage'] = dict(r['usage'])
    return Resp(res)

def stream_resp(split, tool_calls=None, thought=None, truncated=False, usage=None):
    "Build the `Resp` for a streamed step from a finished `StreamSplit` and the backend's own values."
    th = split.thought if thought is None else thought
    tcs = split.tool_calls if tool_calls is None else tool_calls
    res = {'role': 'assistant', 'content': split.text}
    if th: res['channels'] = {'thought': th}
    if tcs: res['tool_calls'] = tcs
    if getattr(split, 'failed', False): res['tool_parse_failed'] = True
    if truncated: res['truncated'] = True
    if usage is not None: res['usage'] = usage
    return Resp(res)

