#: Characters per token. ornith-1.5:9b and qwen3:0.6b measure 3.50 on English prose. 3.25 is lower, so `est_tokens` errs high.
CHARS_PER_TOKEN = 3.25

def est_tokens(text):
    "Estimate the token count of `text` from its length."
    return max(1, math.ceil(len(text) / CHARS_PER_TOKEN)) if text else 0

#: Heading for each message role in `render_prompt`.
ROLE_NAMES = {'user': 'User', 'assistant': 'Assistant', 'tool': 'Tool result', 'system': 'System'}

def render_prompt(hist, sp=''):
    "Render a conversation as one block of text with a heading per message."
    out = [sp] if sp else []
    for m in hist:
        if not (txt := resp_text(m)) and not m.get('tool_calls'): continue
        who = ROLE_NAMES.get(m.get('role'), m.get('role', '?'))
        if m.get('role') == 'tool': who = f"Tool result ({m.get('name', '?')})"
        calls = '\n'.join(
            '<tool_call>\n' + json.dumps({'name': tc_name(tc),
                                          'arguments': tc.get('function', {}).get('arguments') or {}})
            + '\n</tool_call>' for tc in (m.get('tool_calls') or []))
        out.append(f"## {who}\n{txt}{chr(10) + calls if calls else ''}")
    return '\n\n'.join(out)

# %% ../nbs/02_msgs.ipynb #a1342410
def common_prefix_len(a, b):
    "Length of the longest common prefix of sequences `a` and `b`."
    n = 0
    for x, y in zip(a, b):
        if x != y: break
        n += 1
    return n
